import json, re

filepath = "/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-10-projects-provenance-weight-training/9b1b3290-57d1-413f-bf56-b2da5c5109ee/tool-results/mcp-agent-ml-research-read_registry-1778843095164.txt"

with open(filepath, 'r') as f:
    raw = f.read()

data = json.loads(raw)
inner = json.loads(data['result'])
exps = inner['data']['experiments']

# Extract structured data for all experiments
records = []
for exp_id, v in exps.items():
    rec = {
        'exp_id': exp_id,
        'status': v.get('status', 'UNKNOWN'),
        'conclusion': v.get('conclusion', ''),
        'hypothesis': v.get('hypothesis', ''),
        'notes': v.get('notes', ''),
        'failure_reason': v.get('failure_reason', ''),
    }

    # Extract seed
    spec = v.get('spec', {})
    if isinstance(spec, dict):
        rec['seed'] = spec.get('seed', '')
    else:
        rec['seed'] = ''

    # Extract metrics
    metrics = v.get('metrics', {})
    if isinstance(metrics, dict):
        rec['eval_ppl'] = metrics.get('eval_ppl_holdout', metrics.get('eval_ppl', ''))
        rec['eval_loss'] = metrics.get('eval_loss', '')
        rec['train_loss'] = metrics.get('train_loss', '')
        rec['total_steps'] = metrics.get('total_steps', '')
        rec['gpu_hours'] = metrics.get('gpu_hours', '')
        rec['eval_method'] = metrics.get('eval_method', '')
    else:
        rec['eval_ppl'] = rec['eval_loss'] = rec['train_loss'] = ''
        rec['total_steps'] = rec['gpu_hours'] = rec['eval_method'] = ''

    # Extract b value or tau value from command
    command = ''
    if 'reproduce' in v and isinstance(v['reproduce'], dict):
        command = v['reproduce'].get('command', '')
    if not command and 'spec' in v and isinstance(v['spec'], dict):
        command = v['spec'].get('command', '')

    rec['weighting_method'] = ''
    rec['grid_b_value'] = ''
    rec['tau'] = ''
    rec['n_min'] = ''

    if command:
        m = re.search(r'--weighting_method\s+(\S+)', command)
        if m: rec['weighting_method'] = m.group(1)
        m = re.search(r'--grid_b_value\s+(\S+)', command)
        if m: rec['grid_b_value'] = m.group(1)
        m = re.search(r'--tau\s+(\S+)', command)
        if m: rec['tau'] = m.group(1)
        m = re.search(r'--n_min\s+(\S+)', command)
        if m: rec['n_min'] = m.group(1)

    rec['parent'] = v.get('parent', '')
    rec['server'] = v.get('server', '')
    rec['gpu'] = v.get('gpu', '')
    rec['retry_count'] = v.get('retry_count', 0)
    rec['checkpoint_path'] = v.get('checkpoint_path', '')

    reproduce = v.get('reproduce', {})
    if isinstance(reproduce, dict):
        rec['training_hours'] = reproduce.get('training_hours', '')
    else:
        rec['training_hours'] = ''

    records.append(rec)

# Categorize
categories = {}
for r in records:
    eid = r['exp_id']
    wm = r['weighting_method']

    if eid.startswith('grid_b') and (wm == 'grid' or 'grid' in eid):
        cat = 'grid_b_sweep'
    elif eid.startswith('tau_'):
        cat = 'tau_sensitivity_sweep'
    elif eid.startswith('uniform_'):
        cat = 'uniform_baseline'
    elif eid.startswith('adaptive_v2_'):
        cat = 'adaptive_v2'
    elif eid.startswith('adaptive_fix_'):
        cat = 'adaptive_fix'
    elif eid.startswith('adaptive_seed'):
        cat = 'adaptive_original'
    elif eid.startswith('detector_'):
        cat = 'detector'
    elif eid.startswith('datagen_'):
        cat = 'datagen'
    elif eid.startswith('diagnostic_'):
        cat = 'diagnostic'
    elif eid.startswith('nmin'):
        cat = 'n_min_sensitivity'
    elif eid.startswith('golden_ratio'):
        cat = 'golden_ratio_oracle'
    elif eid.startswith('ess_only'):
        cat = 'ess_only_baseline'
    else:
        cat = 'other'

    if cat not in categories:
        categories[cat] = []
    categories[cat].append(r)

# Print structured output
for cat in ['grid_b_sweep', 'uniform_baseline', 'adaptive_original', 'adaptive_v2', 'adaptive_fix', 
            'tau_sensitivity_sweep', 'n_min_sensitivity', 'golden_ratio_oracle', 'ess_only_baseline',
            'diagnostic', 'detector', 'datagen', 'other']:
    if cat not in categories:
        continue
    recs = categories[cat]
    print(f"\n{'='*80}")
    print(f"  CATEGORY: {cat}  ({len(recs)} experiments)")
    print(f"{'='*80}")

    for r in recs:
        print(f"\n  --- {r['exp_id']} ---")
        print(f"  Status:           {r['status']}")
        if r['conclusion']:
            print(f"  Conclusion:       {r['conclusion']}")
        if r['seed']:
            print(f"  Seed:             {r['seed']}")
        if r['weighting_method']:
            print(f"  Weighting method: {r['weighting_method']}")
        if r['grid_b_value']:
            print(f"  Grid b value:     {r['grid_b_value']}")
        if r['tau']:
            print(f"  Tau:              {r['tau']}")
        if r['n_min']:
            print(f"  n_min:            {r['n_min']}")
        if r['eval_ppl'] != '':
            print(f"  Eval PPL:         {r['eval_ppl']}")
        if r['eval_loss'] != '':
            print(f"  Eval loss:        {r['eval_loss']}")
        if r['train_loss'] != '':
            print(f"  Train loss:       {r['train_loss']}")
        if r['total_steps'] != '':
            print(f"  Total steps:      {r['total_steps']}")
        if r['gpu_hours'] != '':
            print(f"  GPU hours:        {r['gpu_hours']}")
        if r['training_hours'] != '':
            print(f"  Training hours:   {r['training_hours']}")
        if r['retry_count']:
            print(f"  Retry count:      {r['retry_count']}")
        if r['checkpoint_path']:
            print(f"  Checkpoint:       {r['checkpoint_path']}")
        if r['parent']:
            print(f"  Parent:           {r['parent']}")
        if r['hypothesis']:
            print(f"  Hypothesis:       {r['hypothesis']}")
        if r['notes']:
            print(f"  Notes:            {r['notes']}")
        if r['failure_reason']:
            print(f"  Failure reason:   {r['failure_reason']}")
        if r['eval_method']:
            print(f"  Eval method:      {r['eval_method']}")

print(f"\n{'='*80}")
print(f"  SUMMARY STATISTICS")
print(f"{'='*80}")
status_counts = {}
conclusion_counts = {}
for r in records:
    s = r['status']
    status_counts[s] = status_counts.get(s, 0) + 1
    c = r['conclusion'] or '(none)'
    conclusion_counts[c] = conclusion_counts.get(c, 0) + 1

print(f"  Total experiments: {len(records)}")
print(f"  Status breakdown:")
for s, c in sorted(status_counts.items()):
    print(f"    {s:<15s} {c}")
print(f"  Conclusion breakdown:")
for s, c in sorted(conclusion_counts.items()):
    print(f"    {s:<15s} {c}")

# PPL leaderboard
ppl_records = [(r['exp_id'], r['eval_ppl'], r['weighting_method'], r['grid_b_value'], r['tau'], r['seed']) 
               for r in records if r['eval_ppl'] != '' and isinstance(r['eval_ppl'], (int, float))]
ppl_records.sort(key=lambda x: x[1])
print(f"\n  PPL Leaderboard (lower is better):")
for eid, ppl, wm, bv, tau, seed in ppl_records:
    extras = []
    if bv: extras.append(f"b={bv}")
    if tau: extras.append(f"tau={tau}")
    estr = ", ".join(extras)
    if estr: estr = f"  ({estr})"
    print(f"    {ppl:>8.3f}  {eid:<30s}  method={wm}{estr}  seed={seed}")

